#!/usr/bin/env python3
"""MOON NEXUS v3 single-file Python build app.

Extracts the complete MOON NEXUS UI/bridge payload to a private runtime folder
and launches MOON_NEXUS_APP.py. Existing MOON intelligence remains external.
"""
from __future__ import annotations
import argparse, base64, io, os, runpy, shutil, sys, zipfile
from pathlib import Path
PAYLOAD = ''
RUNTIME = Path.home() / ".moon_nexus_v3_runtime"

def unpack():
    RUNTIME.mkdir(parents=True, exist_ok=True)
    marker = RUNTIME / ".payload_ready"
    if not marker.exists():
        with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as z:
            z.extractall(RUNTIME)
        marker.write_text("MOON NEXUS v3\n", encoding="utf-8")
    sys.path.insert(0, str(RUNTIME))
    os.chdir(RUNTIME)

def main():
    parser=argparse.ArgumentParser(description="MOON NEXUS v3 single-file Python app")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--test", action="store_true")
    parser.add_argument("--no-browser", action="store_true")
    args=parser.parse_args()
    unpack()
    sys.argv=[str(RUNTIME/'MOON_NEXUS_APP.py')]
    if args.check: sys.argv.append('--check')
    elif args.test: sys.argv.append('--test')
    elif args.no_browser: sys.argv.append('--no-browser')
    runpy.run_path(str(RUNTIME/'MOON_NEXUS_APP.py'), run_name='__main__')

if __name__ == '__main__':
    main()
